-- Stores aspensmitha's site manifest: her categories, pages and map layouts, the 29 spots a photo can be picked
-- for, and the 22 image slots published to fixed addresses. The shared admin app reads it, and the image
-- publisher takes her slots from it instead of the copy embedded in the shared backend.
--
-- The JSON is clientapp/dist/_site/manifest.json from a build of this repo, minified. Its slots are identical
-- to the embedded copy, so storing it republishes nothing.
-- Characters outside ASCII are written as JSON escapes, so the file reads the same whatever encoding a tool assumes.
-- Run after scripts/elysian-0.0.64-migrations.sql. Safe to run again: it replaces the stored manifest.
-- Regenerate this file from a fresh build if the categories, spots or slots change before the site's deploy
-- sends the manifest itself.
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;

DECLARE @TenantId nvarchar(64) = (SELECT [Id] FROM [TenantInfo] WHERE [Identifier] = N'aspensmitha');
IF @TenantId IS NULL
BEGIN
    RAISERROR('Tenant aspensmitha was not found. Nothing was run.', 16, 1);
    RETURN;
END

IF OBJECT_ID(N'[SiteManifest]') IS NULL
BEGIN
    RAISERROR('The SiteManifest table does not exist. Run scripts/elysian-0.0.64-migrations.sql first.', 16, 1);
    RETURN;
END

DECLARE @Json nvarchar(max) = N'{"version":1,"site":{"name":"Aspen Smitha Photography","publicUrl":"https://www.aspensmitha.com","categoryPath":"/portfolio/{category}","storyPath":"/portfolio/{category}/{slug}","sessionPath":"/booking/{slug}","credit":"Aspen Smitha, a Tallahassee, Florida photographer"},"categories":[{"slug":"couples","name":"Couples","hasGallery":true,"hasStories":false,"description":"Tallahassee Couples Photographer | Aspen Smitha Photography","searchTerm":"Couples"},{"slug":"engagements","name":"Engagements","hasGallery":true,"hasStories":false,"description":"Tallahassee Engagement Photographer | Aspen Smitha Photography","searchTerm":"Engagement"},{"slug":"weddings","name":"Weddings","hasGallery":true,"hasStories":true,"description":"Tallahassee Wedding Photographer | Aspen Smitha Photography","searchTerm":"Wedding","storyEyebrow":"A Wedding Story"},{"slug":"maternity","name":"Maternity","hasGallery":true,"hasStories":false,"description":"Tallahassee Maternity Photographer | Aspen Smitha Photography","searchTerm":"Maternity"},{"slug":"family","name":"Family","hasGallery":true,"hasStories":false,"description":"Tallahassee Family Photographer | Aspen Smitha Photography","searchTerm":"Family"},{"slug":"seniors","name":"Seniors","hasGallery":true,"hasStories":false,"description":"Tallahassee Senior Photographer | Aspen Smitha Photography","searchTerm":"Senior Portrait"},{"slug":"grads","name":"Grads","hasGallery":true,"hasStories":false,"description":"Tallahassee Graduation Photographer | Aspen Smitha Photography","searchTerm":"Graduation"},{"slug":"events","name":"Events","hasGallery":false,"hasStories":true,"description":"Tallahassee Event Photographer | Aspen Smitha Photography","searchTerm":"Event","storyEyebrow":"An Event Story"},{"slug":"creative","name":"Creative","hasGallery":true,"hasStories":true,"description":"Not every photoshoot begins with a client inquiry. Sometimes, an idea simply pops into my head, and I can\u2019t help but bring it to life. These creative sessions are offered as complimentary model collaborations in exchange for permission to share the resulting images. Interested in collaborating? Reach out through my contact page!","searchTerm":"Creative","storyEyebrow":"A Creative Story"}],"siteOnlyCategory":{"slug":"site","name":"Site only (not in portfolio)"},"pages":[{"key":"home","name":"Home","path":"/","layout":[{"type":"text"},{"type":"row","variant":"strip","children":[{"type":"spot","spot":"home-hero-1"},{"type":"spot","spot":"home-hero-2"},{"type":"spot","spot":"home-hero-3"},{"type":"spot","spot":"home-hero-4"},{"type":"spot","spot":"home-hero-5"},{"type":"spot","spot":"home-hero-6"},{"type":"spot","spot":"home-hero-7"},{"type":"spot","spot":"home-hero-8"}]},{"type":"row","children":[{"type":"spot","spot":"home-intro","ratio":0.8,"flex":0.8},{"type":"lines","count":3}]},{"type":"row","children":[{"type":"spot","spot":"home-specialty-weddings","ratio":0.8},{"type":"spot","spot":"home-specialty-maternity","ratio":0.8},{"type":"spot","spot":"home-specialty-family","ratio":0.8}]},{"type":"row","children":[{"type":"spot","spot":"home-recent-large","ratio":0.8,"flex":1.4},{"type":"col","children":[{"type":"spot","spot":"home-recent-top"},{"type":"spot","spot":"home-recent-bottom"}]}]},{"type":"text"},{"type":"spot","spot":"home-cta","shape":"banner"}]},{"key":"about","name":"About","path":"/about-me","layout":[{"type":"text"},{"type":"tiles","count":3},{"type":"row","children":[{"type":"spot","spot":"about-story","ratio":0.8,"flex":0.8},{"type":"lines","count":4}]},{"type":"spot","spot":"about-cta","shape":"banner"}]},{"key":"contact","name":"Contact","path":"/contact","layout":[{"type":"text"},{"type":"row","children":[{"type":"spot","spot":"contact-portrait","ratio":0.8,"flex":0.8},{"type":"lines","count":4,"variant":"form"}]}]},{"key":"portfolio","name":"Portfolio","path":"/portfolio","layout":[{"type":"text"},{"type":"grid","columns":3,"children":[{"type":"spot","spot":"portfolio-cover-couples","ratio":0.8},{"type":"spot","spot":"portfolio-cover-engagements","ratio":0.8},{"type":"spot","spot":"portfolio-cover-weddings","ratio":0.8},{"type":"spot","spot":"portfolio-cover-maternity","ratio":0.8},{"type":"spot","spot":"portfolio-cover-family","ratio":0.8},{"type":"spot","spot":"portfolio-cover-seniors","ratio":0.8},{"type":"spot","spot":"portfolio-cover-grads","ratio":0.8},{"type":"spot","spot":"portfolio-cover-events","ratio":0.8},{"type":"spot","spot":"portfolio-cover-creative","ratio":0.8}]}]},{"key":"site","name":"Whole site","path":"/"}],"spots":[{"key":"home-hero-1","label":"Hero strip, photo 1","page":"home"},{"key":"home-hero-2","label":"Hero strip, photo 2","page":"home"},{"key":"home-hero-3","label":"Hero strip, photo 3","page":"home"},{"key":"home-hero-4","label":"Hero strip, photo 4","page":"home"},{"key":"home-hero-5","label":"Hero strip, photo 5","page":"home"},{"key":"home-hero-6","label":"Hero strip, photo 6","page":"home"},{"key":"home-hero-7","label":"Hero strip, photo 7","page":"home"},{"key":"home-hero-8","label":"Hero strip, photo 8","page":"home"},{"key":"home-intro","label":"Intro portrait (\"Hello, I''m Aspen\")","page":"home"},{"key":"home-specialty-weddings","label":"Specialties: Weddings","page":"home"},{"key":"home-specialty-maternity","label":"Specialties: Maternity","page":"home"},{"key":"home-specialty-family","label":"Specialties: Family","page":"home"},{"key":"home-recent-large","label":"Recent Sessions, large photo","page":"home"},{"key":"home-recent-top","label":"Recent Sessions, top right","page":"home"},{"key":"home-recent-bottom","label":"Recent Sessions, bottom right","page":"home"},{"key":"home-cta","label":"Closing banner (\"Inquire Now\")","page":"home"},{"key":"about-story","label":"Story portrait","page":"about"},{"key":"about-cta","label":"Closing banner (\"Let''s chat!\")","page":"about"},{"key":"contact-portrait","label":"Portrait beside the form","page":"contact"},{"key":"portfolio-cover-couples","label":"Couples tile cover","page":"portfolio"},{"key":"portfolio-cover-engagements","label":"Engagements tile cover","page":"portfolio"},{"key":"portfolio-cover-weddings","label":"Weddings tile cover","page":"portfolio"},{"key":"portfolio-cover-maternity","label":"Maternity tile cover","page":"portfolio"},{"key":"portfolio-cover-family","label":"Family tile cover","page":"portfolio"},{"key":"portfolio-cover-seniors","label":"Seniors tile cover","page":"portfolio"},{"key":"portfolio-cover-grads","label":"Grads tile cover","page":"portfolio"},{"key":"portfolio-cover-events","label":"Events tile cover","page":"portfolio"},{"key":"portfolio-cover-creative","label":"Creative tile cover","page":"portfolio"},{"key":"site-default","label":"Fallback for any empty spot (Home & Portfolio)","page":"site"}],"placements":{"recipeVersion":1,"siteDefaultKey":"site-default","slots":[{"key":"home-hero-1","name":"home-hero-strip-photo1","ratio":0.75,"widths":[480,720,1080],"alt":"Featured photograph 1 by Aspen Smitha Photography, Tallahassee"},{"key":"home-hero-2","name":"home-hero-strip-photo2","ratio":0.75,"widths":[480,720,1080],"alt":"Featured photograph 2 by Aspen Smitha Photography, Tallahassee"},{"key":"home-hero-3","name":"home-hero-strip-photo3","ratio":0.75,"widths":[480,720,1080],"alt":"Featured photograph 3 by Aspen Smitha Photography, Tallahassee"},{"key":"home-hero-4","name":"home-hero-strip-photo4","ratio":0.75,"widths":[480,720,1080],"alt":"Featured photograph 4 by Aspen Smitha Photography, Tallahassee"},{"key":"home-hero-5","name":"home-hero-strip-photo5","ratio":0.75,"widths":[480,720,1080],"alt":"Featured photograph 5 by Aspen Smitha Photography, Tallahassee"},{"key":"home-hero-6","name":"home-hero-strip-photo6","ratio":0.75,"widths":[480,720,1080],"alt":"Featured photograph 6 by Aspen Smitha Photography, Tallahassee"},{"key":"home-hero-7","name":"home-hero-strip-photo7","ratio":0.75,"widths":[480,720,1080],"alt":"Featured photograph 7 by Aspen Smitha Photography, Tallahassee"},{"key":"home-hero-8","name":"home-hero-strip-photo8","ratio":0.75,"widths":[480,720,1080],"alt":"Featured photograph 8 by Aspen Smitha Photography, Tallahassee"},{"key":"home-intro","name":"home-intro-portrait-photo1","ratio":0.8,"widths":[500,1000,1500],"alt":"Aspen Smitha, Tallahassee wedding, maternity and family photographer"},{"key":"home-specialty-weddings","name":"home-specialty-weddings-photo1","ratio":0.8,"widths":[420,840,1260],"alt":"Wedding photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"weddings"},{"key":"home-specialty-maternity","name":"home-specialty-maternity-photo1","ratio":0.8,"widths":[420,840,1260],"alt":"Maternity photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"maternity"},{"key":"home-specialty-family","name":"home-specialty-family-photo1","ratio":0.8,"widths":[420,840,1260],"alt":"Family photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"family"},{"key":"home-cta","name":"home-cta-banner-photo1","ratio":2.2,"widths":[880,1320,1760,2400],"alt":"Photography by Aspen Smitha, Tallahassee"},{"key":"portfolio-cover-couples","name":"portfolio-cover-couples-photo1","ratio":0.8,"widths":[400,800,1200],"alt":"Couples photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"couples"},{"key":"portfolio-cover-engagements","name":"portfolio-cover-engagements-photo1","ratio":0.8,"widths":[400,800,1200],"alt":"Engagement photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"engagements"},{"key":"portfolio-cover-weddings","name":"portfolio-cover-weddings-photo1","ratio":0.8,"widths":[400,800,1200],"alt":"Wedding photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"weddings"},{"key":"portfolio-cover-maternity","name":"portfolio-cover-maternity-photo1","ratio":0.8,"widths":[400,800,1200],"alt":"Maternity photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"maternity"},{"key":"portfolio-cover-family","name":"portfolio-cover-family-photo1","ratio":0.8,"widths":[400,800,1200],"alt":"Family photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"family"},{"key":"portfolio-cover-seniors","name":"portfolio-cover-seniors-photo1","ratio":0.8,"widths":[400,800,1200],"alt":"Senior portrait photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"seniors"},{"key":"portfolio-cover-grads","name":"portfolio-cover-grads-photo1","ratio":0.8,"widths":[400,800,1200],"alt":"Graduation photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"grads"},{"key":"portfolio-cover-events","name":"portfolio-cover-events-photo1","ratio":0.8,"widths":[400,800,1200],"alt":"Event photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"events"},{"key":"portfolio-cover-creative","name":"portfolio-cover-creative-photo1","ratio":0.8,"widths":[400,800,1200],"alt":"Creative and editorial photography by Aspen Smitha, Tallahassee photographer","fallbackCategory":"creative"}]}}';

IF ISJSON(@Json) <> 1
BEGIN
    RAISERROR('The manifest is not valid JSON. Nothing was run.', 16, 1);
    RETURN;
END

BEGIN TRANSACTION;

UPDATE [SiteManifest]
SET [Json] = @Json, [Source] = N'seed', [ModifiedByUserId] = N'bootstrap', [ModifiedAt] = SYSDATETIMEOFFSET()
WHERE [TenantId] = @TenantId AND [IsDeleted] = 0;

IF @@ROWCOUNT = 0
    INSERT INTO [SiteManifest] ([Json], [Source], [TenantId],
        [CreatedByUserId], [CreatedAt], [ModifiedByUserId], [ModifiedAt], [IsDeleted])
    VALUES (@Json, N'seed', @TenantId,
        N'bootstrap', SYSDATETIMEOFFSET(), N'bootstrap', SYSDATETIMEOFFSET(), 0);

COMMIT;

SELECT [Source], LEN([Json]) AS [JsonLength], [ModifiedAt],
    (SELECT COUNT(*) FROM OPENJSON([Json], '$.spots')) AS [Spots],
    (SELECT COUNT(*) FROM OPENJSON([Json], '$.placements.slots')) AS [Slots]
FROM [SiteManifest] WHERE [TenantId] = @TenantId AND [IsDeleted] = 0;
